def split_csv(line):
    """Parse one line of CSV and return its fields as a list of strings, or None if malformed."""
    if line == "":
        return [""]

    fields = []
    i = 0

    while i < len(line):
        # Skip comma separator
        if i > 0 and line[i] == ',':
            i += 1
            if i >= len(line):
                # Trailing comma means empty field at the end
                fields.append("")
                return fields

        # Start of a field
        if i < len(line) and line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    # Check for doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i < len(line) and line[i] != ',':
                            return None
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    return None
                field += line[i]
                i += 1
            fields.append(field)

    return fields

